// ---- La sesión del panel de barbero ----
// Lo que se guarda aquí es un pase firmado por el servidor con su fecha de
// caducidad dentro. NO es la clave, y de él no se puede sacar la clave.
// Va en sessionStorage y no en localStorage: al cerrar el navegador se va.
const ADMIN_SESSION_KEY = "felix_admin_session";

function readAdminSession() {
  try {
    const raw = window.sessionStorage.getItem(ADMIN_SESSION_KEY);
    if (!raw) return null;
    const s = JSON.parse(raw);
    if (!s || typeof s.token !== "string" || !s.expiresAt) return null;
    // Caducada es lo mismo que no tenerla. El servidor lo comprueba igual;
    // esto solo evita enseñar el panel un segundo para quitarlo después.
    if (new Date(s.expiresAt).getTime() <= Date.now()) {
      clearAdminSession();
      return null;
    }
    return s;
  } catch {
    return null;
  }
}

function saveAdminSession(s) {
  try { window.sessionStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify(s)); } catch { /* sin sessionStorage se entra igual, solo que hay que repetir la clave */ }
}

function clearAdminSession() {
  try { window.sessionStorage.removeItem(ADMIN_SESSION_KEY); } catch { /* nada que limpiar */ }
}

async function apiGet(path, { auth = false } = {}) {
  const headers = { Accept: "application/json" };
  if (auth) {
    const session = readAdminSession();
    if (!session) {
      const err = new Error("Tu sesión ha caducado. Vuelve a entrar con tu clave.");
      err.reason = "unauthorized";
      err.status = 401;
      throw err;
    }
    headers.Authorization = `Bearer ${session.token}`;
  }
  const res = await fetch(path, { headers });
  const body = await res.json().catch(() => null);
  if (!res.ok || !body || body.ok === false) {
    const err = new Error((body && body.message) || `Error ${res.status}`);
    err.reason = body && body.reason;
    err.status = res.status;
    throw err;
  }
  return body;
}

// Con { auth: true } se adjunta el pase del panel. Solo lo lleva /api/admin:
// reservar una cita no necesita identificarse, y no debe.
async function apiSend(path, method, payload, { auth = false } = {}) {
  const headers = { "Content-Type": "application/json" };
  if (auth) {
    const session = readAdminSession();
    if (!session) {
      const err = new Error("Tu sesión ha caducado. Vuelve a entrar con tu clave.");
      err.reason = "unauthorized";
      err.status = 401;
      throw err;
    }
    headers.Authorization = `Bearer ${session.token}`;
  }
  const res = await fetch(path, {
    method,
    headers,
    body: JSON.stringify(payload),
  });
  const body = await res.json().catch(() => null);
  if (!res.ok || !body || body.ok === false) {
    const err = new Error((body && body.message) || `Error ${res.status}`);
    err.reason = body && body.reason;
    err.status = res.status;
    throw err;
  }
  return body;
}

// El correo de aviso lo manda el Apps Script antiguo, que sigue en pie solo
// para esto. BARBER_EMAIL está vacío, así que hoy no se envía nada de todos
// modos. Mover los avisos fuera de Google es una petición aparte.
async function sendNotification(to, subject, message) {
  if (MAINTENANCE_MODE) return false;
  if (!SHEETS_API_URL || !to) return false;
  try {
    await fetch(SHEETS_API_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ action: "notify", to, subject, message }),
    });
    return true;
  } catch (e) {
    return false;
  }
}

// ---- Saneado en el navegador ----
// Es comodidad para quien escribe, no una garantía: el servidor vuelve a
// validarlo todo, porque esto se puede saltar.
function sanitizeName(v) {
  return String(v || "").replace(/\s+/g, " ").trimStart().slice(0, 80);
}
function sanitizePhoneInput(v) {
  return String(v || "").replace(/[^\d\s+]/g, "").slice(0, 20);
}
function phoneDigits(v) {
  return String(v || "").replace(/\D/g, "");
}
function isPhoneValid(v) {
  return /^[0-9]{9,15}$/.test(phoneDigits(v));
}
function isEmailValid(v) {
  const e = String(v || "").trim();
  return e === "" || /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error("No se pudo leer el archivo"));
    reader.readAsDataURL(file);
  });
}

// Redimensiona y comprime una foto subida desde la galería del teléfono antes de guardarla
async function resizeImageToDataUrl(file, maxSize = 480, quality = 0.72) {
  const rawDataUrl = await readFileAsDataUrl(file);
  try {
    const img = await new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("No se pudo decodificar la imagen"));
      image.src = rawDataUrl;
    });
    let { width, height } = img;
    if (width > height) {
      if (width > maxSize) { height = Math.round(height * (maxSize / width)); width = maxSize; }
    } else {
      if (height > maxSize) { width = Math.round(width * (maxSize / height)); height = maxSize; }
    }
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(img, 0, 0, width, height);
    return canvas.toDataURL("image/jpeg", quality);
  } catch (err) {
    if (rawDataUrl.length > 3500000) {
      throw new Error("Esa foto pesa demasiado. Prueba con otra o hazle una captura de pantalla primero.");
    }
    return rawDataUrl;
  }
}


function buildWhatsAppLink({ name, phone, serviceName, dateLabel, time }) {
  const msg = `Hola! Quiero confirmar mi cita en Félix Barbería 💈\n\nServicio: ${serviceName}\nFecha: ${dateLabel}\nHora: ${time}\nNombre: ${name}\nTeléfono: ${phone}`;
  return `https://wa.me/${BARBER_WHATSAPP}?text=${encodeURIComponent(msg)}`;
}

function buildCancelWhatsAppLink({ name, phone, serviceName, dateLabel, time }) {
  const msg = `Hola! Aviso de que cancelo mi cita en Félix Barbería 🙏\n\nServicio: ${serviceName}\nFecha: ${dateLabel}\nHora: ${time}\nNombre: ${name}\nTeléfono: ${phone}`;
  return `https://wa.me/${BARBER_WHATSAPP}?text=${encodeURIComponent(msg)}`;
}

function buildGoogleCalendarLink({ start, end, serviceName }) {
  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: `Cita en Félix Barbería · ${serviceName}`,
    dates: `${utcCompact(start)}/${utcCompact(end)}`,
    details: `Cita reservada en Félix Barbería (${serviceName}).`,
    location: SHOP_ADDRESS,
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

function buildICSDataUri({ start, end, serviceName }) {
  const ics = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "BEGIN:VEVENT",
    `DTSTART:${icsLocalDate(start)}`,
    `DTEND:${icsLocalDate(end)}`,
    `SUMMARY:Cita en Félix Barbería · ${serviceName}`,
    `DESCRIPTION:Cita reservada en Félix Barbería (${serviceName}).`,
    `LOCATION:${SHOP_ADDRESS}`,
    "END:VEVENT",
    "END:VCALENDAR",
  ].join("\r\n");
  return `data:text/calendar;charset=utf8,${encodeURIComponent(ics)}`;
}

