export default function FelixBarberiaApp() {
  const [view, setView] = useState("inicio"); // inicio | reservar | misCitas | contacto | galeria | admin
  const [menuOpen, setMenuOpen] = useState(false);
  const [initialServiceId, setInitialServiceId] = useState(null);
  const [bookingKey, setBookingKey] = useState(0);
  // Sube cada vez que la sesión del panel deja de valer. Se usa como key del
  // panel, así que subirla lo vuelve a montar y el panel pide la clave otra vez.
  const [adminEpoch, setAdminEpoch] = useState(0);
  const [services, setServicesState] = useState(DEFAULT_SERVICES);
  const [barbers, setBarbersState] = useState(DEFAULT_BARBERS);
  const [appointments, setAppointmentsState] = useState(initialAppointments);
  const [blockedRanges, setBlockedRangesState] = useState(initialBlockedRanges);
  const [blockedDays, setBlockedDaysState] = useState(initialBlockedDays);
  const [festivos, setFestivosState] = useState(initialFestivos);
  const [vacationRanges, setVacationRangesState] = useState(initialVacationRanges);
  const [portfolio, setPortfolioState] = useState(DEFAULT_PORTFOLIO);
  // La lista de espera y las citas con nombre y teléfono ya NO vienen en la
  // carga pública: las trae /api/admin-data cuando Félix entra en su panel.
  const [waitlist, setWaitlistState] = useState([]);
  const [adminAppointments, setAdminAppointments] = useState([]);
  const [schedule, setScheduleState] = useState(DEFAULT_SCHEDULE);
  // Reservas temporales vivas: las horas que alguien está rellenando ahora
  // mismo. Se restan de la disponibilidad, igual que una cita.
  const [holds, setHoldsState] = useState([]);

  const [loadError, setLoadError] = useState(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const d = await apiGet("/api/bootstrap");
        if (!mounted) return;
        setServicesState(d.services);
        setBarbersState(d.barbers);
        setAppointmentsState(d.appointments);
        setBlockedRangesState(d.blockedRanges);
        setBlockedDaysState(d.blockedDays);
        setFestivosState(d.festivos);
        setVacationRangesState(d.vacationRanges);
        setScheduleState(d.schedule);
        setHoldsState(d.holds || []);
        setLoadError(null);
      } catch (e) {
        if (!mounted) return;
        // Antes, un fallo aquí dejaba la web con los datos de ejemplo del
        // código: parecía funcionar y enseñaba horas libres que no lo estaban.
        // Ahora se dice.
        setLoadError(e.message || "No se han podido cargar los datos.");
      }
    })();
    return () => { mounted = false; };
  }, []);

  // Durante el mantenimiento ninguna escritura toca ni el estado local ni el almacén:
  // avisa al usuario y no cambia nada, para que nunca parezca que se guardó algo que no se guardó.
  function blockedByMaintenance() {
    if (!MAINTENANCE_MODE) return false;
    if (typeof window !== "undefined") window.alert(MAINTENANCE_MSG);
    return true;
  }

  // Guarda una colección del panel y, si el servidor la rechaza, deshace el
  // cambio en pantalla y lo dice. Nunca se queda una pantalla mostrando algo
  // que la base de datos no aceptó.
  async function saveCollection(collection, next, apply, previous) {
    if (blockedByMaintenance()) return false;
    apply(next);
    try {
      await apiSend("/api/admin", "POST", { collection, items: next }, { auth: true });
      return true;
    } catch (e) {
      apply(previous);
      // Sesión caducada, pase inválido, o la clave sin configurar en el
      // servidor: en los tres casos hay que volver a la pantalla de clave. El
      // cambio ya se ha deshecho arriba, así que en pantalla no queda nada que
      // la base de datos no haya aceptado.
      if (e.status === 401 || e.status === 503) {
        clearAdminSession();
        setAdminEpoch((n) => n + 1);
      }
      if (typeof window !== "undefined") window.alert(`No se ha podido guardar: ${e.message}`);
      return false;
    }
  }

  async function setServices(next)       { return saveCollection("services", next, setServicesState, services); }
  async function setBarbers(next)        { return saveCollection("barbers", next, setBarbersState, barbers); }
  async function setBlockedRanges(next)  { return saveCollection("blockedRanges", next, setBlockedRangesState, blockedRanges); }
  async function setBlockedDays(next)    { return saveCollection("blockedDays", next, setBlockedDaysState, blockedDays); }
  async function setFestivos(next)       { return saveCollection("festivos", next, setFestivosState, festivos); }
  async function setVacationRanges(next) { return saveCollection("vacationRanges", next, setVacationRangesState, vacationRanges); }
  async function setWaitlist(next)       { return saveCollection("waitlist", next, setWaitlistState, waitlist); }
  async function setSchedule(next)       { return saveCollection("schedule", next, setScheduleState, schedule); }

  // Apuntarse a la lista de espera lo hace un CLIENTE, no Félix, así que va
  // por su propia ruta pública — que solo sabe añadir una fila. El panel sigue
  // usando setWaitlist, identificado, para gestionarla y borrar de ella.
  async function joinWaitlist(entry) {
    if (blockedByMaintenance()) throw new Error(MAINTENANCE_MSG);
    await apiSend("/api/waitlist", "POST", {
      name: entry.name,
      phone: entry.phone,
      service: entry.service,
      dateKey: entry.dateKey,
    });
    setWaitlistState((prev) => [...prev, entry]);
  }

  // La galería sigue con las fotos del código: guardar imágenes pide
  // almacenamiento de ficheros, no una columna de texto. Petición aparte.
  function setPortfolio(next) { setPortfolioState(next); }

  // Los datos que solo ve el panel: citas con nombre y teléfono, y la lista de
  // espera. Van por su propia ruta, que exige la clave. Si la sesión ya no
  // vale, se vuelve a pedir en vez de dejar el panel a medias.
  async function loadAdminData() {
    try {
      const d = await apiGet("/api/admin-data", { auth: true });
      setAdminAppointments(d.appointments);
      setWaitlistState(d.waitlist);
      return d.appointments;
    } catch (e) {
      if (e.status === 401 || e.status === 503) {
        clearAdminSession();
        setAdminEpoch((n) => n + 1);
        return [];
      }
      throw e;
    }
  }

  // Crea una cita, o el grupo entero si son varias personas. Devuelve SIEMPRE
  // una lista con las citas creadas, o lanza un error con un mensaje que se
  // puede enseñar tal cual.
  async function createAppointment(data) {
    if (blockedByMaintenance()) throw new Error(MAINTENANCE_MSG);
    const body = await apiSend("/api/appointments", "POST", data);
    // Al estado público solo van los BLOQUES: cuándo empiezan y cuánto duran.
    // Las citas enteras se las queda quien las ha reservado.
    const created = body.appointments || [body.appointment];
    setAppointmentsState((prev) => [
      ...prev,
      ...created.map((a) => ({ dateKey: a.dateKey, time: a.time, barberId: a.barberId, duration: a.duration })),
    ]);
    return created;
  }

  // Cancela. No borra: marca. Así queda el rastro de que la cita existió.
  // No se toca el estado a mano: se relee, porque lo que hay en memoria son
  // bloques sin id y no habría por dónde encontrar el que sobra.
  async function cancelAppointment(id) {
    if (blockedByMaintenance()) throw new Error(MAINTENANCE_MSG);
    await apiSend("/api/appointments", "PATCH", { id, status: "cancelled" });
    await refreshAppointments();
  }

  // Anula la reserva entera de un grupo de una sola vez. Quitar a una persona
  // suelta sigue siendo cancelAppointment con su id: las demás se quedan con
  // la hora que ya tenían.
  async function cancelAppointmentGroup(groupId) {
    if (blockedByMaintenance()) throw new Error(MAINTENANCE_MSG);
    await apiSend("/api/appointments", "PATCH", { groupId });
    await refreshAppointments();
  }

  async function setAppointmentNoShow(id, value) {
    if (blockedByMaintenance()) throw new Error(MAINTENANCE_MSG);
    const body = await apiSend("/api/appointments", "PATCH", { id, status: value ? "no_show" : "booked" });
    return body.appointment;
  }

  // Las reservas temporales recién leídas, para poder consultarlas justo
  // después de un refresco sin esperar a que React vuelva a pintar.
  const latestHoldsRef = useRef([]);
  useEffect(() => { latestHoldsRef.current = holds; }, [holds]);

  // Guarda la hora elegida mientras el cliente rellena sus datos. Es una
  // comodidad, no una garantía: si falla, quien reserva no se entera y sigue
  // adelante. La garantía contra el solape sigue siendo la base de datos.
  async function createHold(data) {
    const body = await apiSend("/api/holds", "POST", data);
    return body.hold;
  }

  // Suelta la hora en cuanto se sabe que ya no hace falta. Caducar es la red
  // de seguridad, no el mecanismo normal.
  async function releaseHold(id) {
    if (!id) return;
    try {
      await apiSend("/api/holds", "DELETE", { id });
    } catch {
      // Si no se suelta, caduca sola en unos minutos. Nunca es motivo para
      // enseñarle un error a nadie.
    }
    setHoldsState((prev) => prev.filter((h) => h.id !== id));
  }

  // Relee la disponibilidad real justo antes de confirmar. Ya no es la única
  // defensa contra dos reservas a la vez —de eso se encarga la base de datos—
  // pero evita enseñar como libre un hueco que acaban de ocupar.
  async function refreshAppointments() {
    const d = await apiGet("/api/bootstrap");
    setAppointmentsState(d.appointments);
    setHoldsState(d.holds || []);
    latestHoldsRef.current = d.holds || [];
    return d.appointments;
  }

  function goReservar(serviceId) {
    setInitialServiceId(serviceId || null);
    setBookingKey((k) => k + 1);
    setView("reservar");
    setMenuOpen(false);
  }
  function goTo(v) {
    setView(v);
    setMenuOpen(false);
  }

  const shared = { services, setServices, barbers, setBarbers, appointments, holds, latestHoldsRef, createHold, releaseHold, createAppointment, cancelAppointment, cancelAppointmentGroup, setAppointmentNoShow, refreshAppointments, blockedRanges, setBlockedRanges, blockedDays, setBlockedDays, festivos, setFestivos, vacationRanges, setVacationRanges, portfolio, setPortfolio, waitlist, setWaitlist, joinWaitlist, schedule, setSchedule };

  return (
    <div style={{ fontFamily: "Inter, sans-serif", background: "#0B0B0A", minHeight: "100vh", color: BONE }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,500;0,700;1,600&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        body { margin: 0; }
        .display { font-family: 'Playfair Display', serif; }
        .wood-bg {
          background-image:
            radial-gradient(ellipse at 50% 0%, rgba(201,162,39,0.10), transparent 60%),
            repeating-linear-gradient(90deg, rgba(255,255,255,0.015) 0px, rgba(255,255,255,0.015) 2px, transparent 2px, transparent 90px),
            linear-gradient(180deg, #0B0B0A, #121110 60%, #0B0B0A);
        }
        .gold-btn { background: linear-gradient(180deg, ${GOLD_LIGHT}, ${GOLD}); color: #1a1408; border: none; }
        .gold-btn:hover { filter: brightness(1.08); }
        .gold-btn:disabled { opacity: 0.5; cursor: not-allowed; }
        .ghost-btn { background: transparent; border: 1px solid rgba(255,255,255,0.3); color: ${BONE}; }
        .ghost-btn:hover { border-color: ${GOLD}; background: rgba(201,162,39,0.08); }
        .card { background: #161513; border: 1px solid rgba(255,255,255,0.14); }
        button.card { font-family: inherit; color: inherit; }
        /* El horario, en dos columnas cuando hay sitio y en una cuando no.
           "09:30–13:30 y 16:30–20:00" no cabe a media pantalla en un móvil
           estrecho, y partido en dos líneas se lee peor que en columna. */
        .horario-tabla { display: grid; grid-auto-flow: row; gap: 9px 18px; }
        @media (min-width: 400px) { .horario-tabla { grid-auto-flow: column; grid-auto-columns: 1fr; } }
        input, select { font-family: 'Inter', sans-serif; }
        ::selection { background: rgba(201,162,39,0.35); }
        @media (prefers-reduced-motion: no-preference) {
          .fade-in { animation: fadeIn 0.35s ease both; }
        }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(6px);} to { opacity:1; transform: translateY(0);} }
        button:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid ${GOLD}; outline-offset: 2px; }
      `}</style>

      <TopChrome menuOpen={menuOpen} setMenuOpen={setMenuOpen} onAdmin={() => goTo("admin")} onInicio={() => goTo("inicio")} onMisCitas={() => goTo("misCitas")} onContacto={() => goTo("contacto")} onGaleria={() => goTo("galeria")} />

      <div className="wood-bg" style={{ paddingBottom: 78, minHeight: "100vh" }}>
        {MAINTENANCE_MODE && <MaintenanceBanner />}
        {loadError && <LoadErrorBanner message={loadError} />}
        {view === "inicio" && <Inicio services={services} onReservar={goReservar} schedule={schedule} onContacto={() => goTo("contacto")} />}
        {view === "reservar" && (MAINTENANCE_MODE ? <MaintenanceCard /> : <ClientBooking key={bookingKey} {...shared} initialServiceId={initialServiceId} />)}
        {view === "misCitas" && <MisCitas {...shared} />}
        {view === "contacto" && <Contacto schedule={schedule} />}
        {view === "galeria" && <Galeria portfolio={portfolio} barbers={barbers} />}
        {/* El panel ve lo suyo por su propia ruta, con la clave. Estas dos
            sustituyen a las públicas, que ya no llevan datos de nadie. */}
        {view === "admin" && <AdminPanel key={adminEpoch} {...shared} appointments={adminAppointments} refreshAppointments={loadAdminData} />}
      </div>

      <BottomNav view={view} onInicio={() => goTo("inicio")} onMisCitas={() => goTo("misCitas")} onReservar={() => goReservar(null)} onContacto={() => goTo("contacto")} />
    </div>
  );
}

